(async () => {
  if (!game.user?.isGM) {
    ui.notifications?.warn?.("GM only: cannot move Items.");
    return;
  }

  const DOC_TYPE = "Item"; // Change to "Actor", "JournalEntry", etc. if needed.

  const folders = (game.folders?.contents ?? []).filter(f => f.type === DOC_TYPE);
  const folderById = new Map(folders.map(f => [f.id, f]));

  const getParentId = (f) => f.folder?.id ?? f.parent?.id ?? null;

  const pathFor = (f) => {
    const parts = [f.name];
    let cur = f;
    let guard = 0;
    while (guard++ < 50) {
      const pid = getParentId(cur);
      if (!pid) break;
      const p = folderById.get(pid);
      if (!p) break;
      parts.unshift(p.name);
      cur = p;
    }
    return parts.join("/");
  };

  const folderRows = folders
    .map(f => ({ id: f.id, label: pathFor(f) }))
    .sort((a, b) => a.label.localeCompare(b.label, undefined, { sensitivity: "base" }));

  const labelById = new Map(folderRows.map(r => [r.id, r.label]));

  const optionsHtml = (includeRoot) => {
    const rootOpt = includeRoot ? `<option value="">(top level / no folder)</option>` : "";
    return rootOpt + folderRows.map(r => `<option value="${r.id}">${r.label}</option>`).join("");
  };

  const content = `
<form>
  <div class="form-group">
    <label>Source folder</label>
    <select name="sourceFolder">${optionsHtml(true)}</select>
  </div>
  <div class="form-group">
    <label>Destination folder</label>
    <select name="destFolder">${optionsHtml(true)}</select>
  </div>
  <div class="form-group">
    <label>Options</label>
    <div class="form-fields">
      <label><input type="checkbox" name="includeSubfolders"> Include subfolders</label>
    </div>
  </div>
</form>
  `;

  const collectFolderTree = (rootId) => {
    const ids = new Set();
    const stack = [rootId];
    while (stack.length) {
      const id = stack.pop();
      if (!id || ids.has(id)) continue;
      ids.add(id);
      for (const f of folders) {
        if (getParentId(f) === id) stack.push(f.id);
      }
    }
    return ids;
  };

  const getCollection = () => (
    game.collections?.get(DOC_TYPE) ||
    (DOC_TYPE === "Item" ? game.items : null)
  );

  new Dialog({
    title: `Move ${DOC_TYPE} documents`,
    content,
    buttons: {
      move: {
        label: "Move",
        callback: async (html) => {
          const srcId = String(html.find('[name="sourceFolder"]').val() ?? "");
          const destId = String(html.find('[name="destFolder"]').val() ?? "");
          const includeSub = Boolean(html.find('[name="includeSubfolders"]').is(":checked"));

          if (srcId === destId) {
            ui.notifications?.warn?.("Source and destination are the same. Nothing to do.");
            return;
          }

          const collection = getCollection();
          if (!collection) {
            ui.notifications?.error?.(`No collection found for type: ${DOC_TYPE}`);
            return;
          }

          const docs = collection.contents ?? Array.from(collection ?? []);
          const folderIds = srcId
            ? (includeSub ? collectFolderTree(srcId) : new Set([srcId]))
            : null;

          const toMove = docs.filter(doc => {
            const fid = doc.folder?.id ?? doc.folder ?? null;
            if (srcId) return fid && folderIds?.has(fid);
            return !fid; // top-level only
          });

          if (!toMove.length) {
            ui.notifications?.info?.("No documents found to move.");
            return;
          }

          const srcLabel = srcId ? (labelById.get(srcId) || srcId) : "(top level)";
          const dstLabel = destId ? (labelById.get(destId) || destId) : "(top level)";

          const ok = await Dialog.confirm({
            title: "Confirm move",
            content: `<p>Move ${toMove.length} ${DOC_TYPE} document(s) from <strong>${srcLabel}</strong> to <strong>${dstLabel}</strong>?</p>`
          });
          if (!ok) return;

          const updates = toMove.map(d => ({ _id: d.id, folder: destId || null }));

          const docClass = collection.documentClass ?? globalThis[DOC_TYPE];
          if (docClass?.updateDocuments) {
            await docClass.updateDocuments(updates);
          } else {
            for (const doc of toMove) {
              await doc.update({ folder: destId || null });
            }
          }

          ui.notifications?.info?.(`Moved ${updates.length} ${DOC_TYPE} document(s) to ${dstLabel}.`);
        }
      },
      cancel: { label: "Cancel" }
    },
    default: "move"
  }).render(true);
})();
